    21	import TermsStep from './TermsStep';
    22	
    23	type EnablePaymentsPageOnyxProps = {
    24	    /** The user's wallet */
    25	    userWallet: OnyxEntry<UserWallet>;
    26	};
    27	
    28	type EnablePaymentsPageProps = EnablePaymentsPageOnyxProps;
    29	
    30	function EnablePaymentsPage({userWallet}: EnablePaymentsPageProps) {
    31	    const {translate} = useLocalize();
    32	    const {isOffline} = useNetwork();
    33	
    34	    const {isPendingOnfidoResult, hasFailedOnfido} = userWallet ?? {};
    35	
    36	    useEffect(() => {
    37	        if (isOffline) {
    38	            return;
    39	        }
    40	
    41	        // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
    42	        if (isPendingOnfidoResult || hasFailedOnfido) {
    43	            Navigation.navigate(ROUTES.SETTINGS_WALLET, CONST.NAVIGATION.TYPE.UP);
    44	            return;
    45	        }
    46	
    47	        Wallet.openEnablePaymentsPage();
    48	    }, [isOffline, isPendingOnfidoResult, hasFailedOnfido]);
    49	
    50	    if (isEmptyObject(userWallet)) {
    51	        return <FullScreenLoadingIndicator />;
    52	    }
    53	
    54	    return (
    55	        <ScreenWrapper
    56	            shouldShowOfflineIndicator={userWallet?.currentStep !== CONST.WALLET.STEP.ONFIDO}
    57	            includeSafeAreaPaddingBottom={false}
    58	            testID={EnablePaymentsPage.displayName}
    59	        >
    60	            {() => {
    61	                if (userWallet?.errorCode === CONST.WALLET.ERROR.KYC) {
    62	                    return (
    63	                        <>
    64	                            <HeaderWithBackButton
    65	                                title={translate('additionalDetailsStep.headerTitle')}
    66	                                onBackButtonPress={() => Navigation.goBack(ROUTES.SETTINGS_WALLET)}
    67	                            />
    68	                            <FailedKYC />
    69	                        </>
    70	                    );
    71	                }
    72	
    73	                const currentStep = userWallet?.currentStep || CONST.WALLET.STEP.ADDITIONAL_DETAILS;
    74	
    75	                switch (currentStep) {
    76	                    case CONST.WALLET.STEP.ADDITIONAL_DETAILS:
    77	                    case CONST.WALLET.STEP.ADDITIONAL_DETAILS_KBA:
    78	                        return <AdditionalDetailsStep />;
    79	                    case CONST.WALLET.STEP.ONFIDO:
    80	                        return <OnfidoStep />;
    81	                    case CONST.WALLET.STEP.TERMS:
    82	                        return <TermsStep userWallet={userWallet} />;
    83	                    case CONST.WALLET.STEP.ACTIVATE:
    84	                        return <ActivateStep userWallet={userWallet} />;
    85	                    default:
    86	                        return null;
    87	                }
    88	            }}
    89	        </ScreenWrapper>
    90	    );
    91	}
