    17	            return;
    18	        }
    19	
    20	        StatusBar.setBackgroundColor(color);
    21	    };
    22	
    23	    const hideModal = () => {
    24	        setStatusBarColor(previousStatusBarColor);
    25	        onModalHide();
    26	        if ((window.history.state as WindowState)?.shouldGoBack) {
    27	            window.history.back();
    28	        }
    29	    };
    30	
    31	    const handlePopStateRef = useRef(() => {
    32	        rest.onClose();
    33	    });
    34	
    35	    const showModal = () => {
    36	        const statusBarColor = StatusBar.getBackgroundColor() ?? theme.appBG;
    37	
    38	        const isFullScreenModal = type === CONST.MODAL.MODAL_TYPE.CENTERED || type === CONST.MODAL.MODAL_TYPE.CENTERED_UNSWIPEABLE || type === CONST.MODAL.MODAL_TYPE.RIGHT_DOCKED;
    39	
    40	        if (statusBarColor) {
    41	            setPreviousStatusBarColor(statusBarColor);
    42	            // If it is a full screen modal then match it with appBG, otherwise we use the backdrop color
    43	            setStatusBarColor(isFullScreenModal ? theme.appBG : StyleUtils.getThemeBackgroundColor(statusBarColor));
    44	        }
    45	
    46	        if (shouldHandleNavigationBack) {
